import { describe, it, expect } from "vitest";
import type { StarSystem } from "@/domain/StarSystem";
import { generateQuestBoard } from "@/systems/quests/QuestGenerator";

/**
 * "Местный подряд" (local courier contract) is generated by buildLocalDelivery,
 * which only fires when no other system is reachable. An isolated single-system
 * galaxy (no connections) makes reachable.length === 0, so every non-text board
 * slot falls back to the local delivery quest.
 */
function isolatedSystem(): StarSystem {
  return {
    id: "ISO",
    name: "Захолустье",
    connections: [],
    planets: [{ id: "ISO_p1", isHabitable: true }],
  } as unknown as StarSystem;
}

describe("Местный подряд (local delivery) quest copy", () => {
  it("describes the real mechanic (buy on the market, deliver in-system) — not fictional orbital warehouses", () => {
    const board = generateQuestBoard({
      systems: [isolatedSystem()],
      originSystemId: "ISO",
      planetId: "ISO_p1",
      day: 0,
      seed: "seed",
      count: 5,
      textRatio: 0,
    });

    const local = board.find((q) => q.template.title === "Местный подряд");
    expect(local).toBeDefined();
    if (!local) return;

    const desc = local.template.description;
    // The old copy promised "развезти ... по орбитальным складам" — multiple drop
    // points that the mechanic never had. It must be gone.
    expect(desc).not.toContain("орбитальн");
    expect(desc).not.toContain("развезти");
    // The new copy must tell the player to buy the cargo on the market and that
    // delivery happens in the current system without jumps.
    expect(desc).toMatch(/рынк|закуп|купи/i);
    expect(desc).toContain("Захолустье");

    // Mechanic unchanged: one COLLECT_ITEM objective with a real cargo amount,
    // no jumps, target system is the origin.
    const collect = local.template.objectives.find(
      (o) => o.type === "COLLECT_ITEM",
    );
    expect(collect).toBeDefined();
    expect(collect!.targetAmount).toBeGreaterThanOrEqual(4);
    expect(local.jumps).toBe(0);
    expect(local.targetSystemId).toBe("ISO");
    // template.targetSystemId must match so acceptBoardQuest stores it on the
    // accepted Quest; without this, checkDeliveryQuestCompletion never fires.
    expect(local.template.targetSystemId).toBe("ISO");

    // The copy must state HOW MUCH to buy: the numeric targetAmount appears in
    // the description so the player is not left guessing the quantity.
    expect(desc).toContain(String(collect!.targetAmount));
    // ...and the cargo label so the player knows WHAT to buy.
    const cargoHighlight = local.highlights.find((h) => h.label === "Груз");
    expect(cargoHighlight).toBeDefined();
    expect(desc).toContain(cargoHighlight!.value);

    // The objective line is self-describing: it carries the amount so the
    // journal's COLLECT_ITEM row tells the player the quantity at a glance.
    expect(collect!.description).toContain(String(collect!.targetAmount));
  });

  it("names the in-system destination planet in the contract copy (no jumps)", () => {
    // Task 1 goal: the copy must tell the player WHERE the goods go — the
    // in-system destination planet by name — and that it needs no jumps. Without
    // this assertion a regression dropping the destination (the exact "can't tell
    // where to deliver" bug this plan fixes) would ship green.
    const system = {
      id: "ISO",
      name: "Захолустье",
      connections: [],
      planets: [{ id: "ISO_p1", name: "Дальний Хутор", isHabitable: true }],
    } as unknown as StarSystem;

    const board = generateQuestBoard({
      systems: [system],
      originSystemId: "ISO",
      planetId: "ISO_p1",
      day: 0,
      seed: "seed",
      count: 5,
      textRatio: 0,
    });

    const local = board.find((q) => q.template.title === "Местный подряд");
    expect(local).toBeDefined();
    if (!local) return;

    const desc = local.template.description;
    expect(desc).toContain("Дальний Хутор");
    expect(desc).toContain("без прыжков");
  });

  it("resolves a real SYSTEM id (origin's board system) even when origin is unknown — never a planet id", () => {
    // originSystemId is NOT present in `systems`, forcing origin === null inside
    // buildLocalDelivery. Previously the fallback was `planetId` (a PLANET id),
    // which made checkDeliveryQuestCompletion (system-level match) never fire.
    const board = generateQuestBoard({
      systems: [isolatedSystem()],
      originSystemId: "GHOST_SYS",
      planetId: "ISO_p1",
      day: 0,
      seed: "seed",
      count: 5,
      textRatio: 0,
    });

    const local = board.find((q) => q.template.title === "Местный подряд");
    expect(local).toBeDefined();
    if (!local) return;

    // The target system id must be the canonical system id (originSystemId),
    // not the issuing planet id, so completion can match the current system.
    expect(local.template.targetSystemId).toBe("GHOST_SYS");
    expect(local.targetSystemId).toBe("GHOST_SYS");
    expect(local.template.targetSystemId).not.toBe("ISO_p1");
  });
});
